UPDATE public.website_templates SET default_sections_json = '[{"section_type": "hero", "content_json": {"heading": "The Riverbend County Bar Association", "subheading": "Advancing the practice of law and serving our community since 1923", "cta_label": "Become a Member", "cta_url": "/join"}}, {"section_type": "feature_grid", "content_json": {"heading": "What membership gives you", "items": [{"title": "CLE Programs", "body": "Earn required credits through live seminars and on-demand courses taught by leading practitioners."}, {"title": "A Real Network", "body": "Practice-area sections, committees, and events that connect you with the attorneys you''ll work with for decades."}, {"title": "Mentorship", "body": "Structured one-to-one pairings that help new lawyers find their footing and give veterans a legacy."}]}}, {"section_type": "cta", "content_json": {"heading": "Join 1,400 attorneys who call this bar home", "cta_label": "Become a Member", "cta_url": "/join"}}]'::jsonb, updated_at = now() WHERE is_global = true AND name = 'Bar Association Homepage';
UPDATE public.website_templates SET default_sections_json = '[{"section_type": "hero", "content_json": {"heading": "2027 Annual Convention", "subheading": "Three days of CLE, connection, and celebration on the riverfront — June 10–12", "cta_label": "Register Now", "cta_url": "#register"}}, {"section_type": "event_details", "content_json": {"date": "June 10–12", "location": "Riverfront Convention Center, 400 Water Street", "schedule": "Thursday: Opening keynote & welcome reception · Friday: CLE tracks & President''s dinner · Saturday: Section meetings & closing brunch"}}, {"section_type": "speaker_cards", "content_json": {"heading": "Featured Speakers", "speakers": [{"name": "Hon. Maria Delgado (Ret.)", "title": "Former Chief Judge, Court of Appeals", "topic": "The Changing Courtroom"}, {"name": "Prof. Daniel Okafor", "title": "Ellis School of Law", "topic": "AI and the Duty of Competence"}, {"name": "Sarah Lindqvist", "title": "Managing Partner, Lindqvist & Cole", "topic": "Building a Firm People Don''t Leave"}]}}, {"section_type": "sponsor_grid", "content_json": {"heading": "Thank You to Our Sponsors", "sponsors": [{"name": "Meridian Legal Technologies", "tier": "Platinum"}, {"name": "First Harbor Bank", "tier": "Gold"}, {"name": "Castellan Court Reporting", "tier": "Silver"}]}}, {"section_type": "faq", "content_json": {"items": [{"question": "How many CLE credits can I earn?", "answer": "Up to 12.5 credits, including 2.0 ethics credits, across all three days."}, {"question": "Is there a discounted rate?", "answer": "Yes — young lawyers (under 5 years in practice), government attorneys, and students receive reduced registration."}, {"question": "Can I bring a guest to evening events?", "answer": "Guest tickets for the welcome reception and President''s dinner are available during registration."}]}}]'::jsonb, updated_at = now() WHERE is_global = true AND name = 'Annual Convention Landing Page';
UPDATE public.website_templates SET default_sections_json = '[{"section_type": "hero", "content_json": {"heading": "Ethics in the Age of AI", "subheading": "A 1.0-credit ethics CLE — live webinar with Q&A"}}, {"section_type": "event_details", "content_json": {"date": "Thursday, March 4 · 12:00–1:00 PM", "location": "Online (Zoom link sent after registration)", "credits": "1.0 Ethics"}}, {"section_type": "text", "content_json": {"heading": "What you''ll learn", "body": "Generative AI is already in your practice, whether you''ve adopted it or not. This session covers the competence and confidentiality obligations that govern AI use, what to put in your engagement letters, how to supervise AI-assisted work product, and where regulators are heading. You''ll leave with a one-page AI policy checklist you can adapt for your firm."}}, {"section_type": "cta", "content_json": {"heading": "Reserve your seat", "cta_label": "Register", "cta_url": "#"}}]'::jsonb, updated_at = now() WHERE is_global = true AND name = 'CLE Event Page';
UPDATE public.website_templates SET default_sections_json = '[{"section_type": "hero", "content_json": {"heading": "Partner With Our Legal Community", "subheading": "Put your brand in front of 1,400 attorneys and the firms they lead"}}, {"section_type": "pricing_tiers", "content_json": {"heading": "Sponsorship Tiers", "tiers": [{"name": "Platinum", "price": "$10,000", "features": ["Premier logo placement at all events", "10 convention passes", "Speaking opportunity at one section meeting", "Featured in every monthly newsletter"]}, {"name": "Gold", "price": "$5,000", "features": ["Logo placement at major events", "5 convention passes", "Quarterly newsletter feature"]}, {"name": "Silver", "price": "$2,500", "features": ["Sponsor listing on website and programs", "2 convention passes"]}]}}, {"section_type": "contact_form", "content_json": {"heading": "Let''s talk about the right fit"}}]'::jsonb, updated_at = now() WHERE is_global = true AND name = 'Sponsorship Opportunities';
UPDATE public.website_templates SET default_sections_json = '[{"section_type": "hero", "content_json": {"heading": "The Mentorship Program", "subheading": "Every great lawyer had someone who showed them the way. Be that person — or find yours."}}, {"section_type": "feature_grid", "content_json": {"items": [{"title": "For Mentors", "body": "Give an hour a month. Shape a career. Mentors consistently tell us they get back more than they give."}, {"title": "For Mentees", "body": "Get matched with an experienced attorney in your practice area for candid guidance you can''t find in a book."}, {"title": "Thoughtfully Matched", "body": "Pairings are curated by practice area, career stage, and goals — never random."}]}}, {"section_type": "cta", "content_json": {"heading": "Ready to get matched?", "cta_label": "Apply Now", "cta_url": "#"}}]'::jsonb, updated_at = now() WHERE is_global = true AND name = 'Mentorship Program';
UPDATE public.website_templates SET default_sections_json = '[{"section_type": "hero", "content_json": {"heading": "The Pro Bono Committee", "subheading": "Expanding access to justice, one case at a time"}}, {"section_type": "text", "content_json": {"heading": "About this committee", "body": "The Pro Bono Committee coordinates volunteer opportunities with legal aid partners, runs the annual Pro Bono Week clinics, and recognizes members whose service goes above and beyond. We meet the second Tuesday of each month — newcomers are always welcome."}}, {"section_type": "committee_cards", "content_json": {"members": [{"name": "James Whitfield", "role": "Chair", "firm": "Whitfield Law Group"}, {"name": "Anita Rao", "role": "Vice Chair", "firm": "Legal Aid Alliance"}, {"name": "Tom Kowalski", "role": "Secretary", "firm": "Kowalski & Associates"}]}}, {"section_type": "cta", "content_json": {"heading": "Join this committee", "cta_label": "Express Interest", "cta_url": "#"}}]'::jsonb, updated_at = now() WHERE is_global = true AND name = 'Committee Page';
UPDATE public.website_templates SET default_sections_json = '[{"section_type": "hero", "content_json": {"heading": "Why Become a Member", "subheading": "Benefits that grow your practice — and a community that has your back"}}, {"section_type": "feature_grid", "content_json": {"items": [{"title": "CLE, Covered", "body": "Members attend most live CLE programs free and get deep discounts on the rest."}, {"title": "Referral Network", "body": "Practice-area sections and the member directory put your name in front of colleagues who send work."}, {"title": "Mentorship", "body": "Structured pairings for new lawyers; leadership and teaching opportunities for veterans."}, {"title": "A Voice", "body": "Committees, sections, and board service — help shape the profession in our community."}]}}, {"section_type": "testimonials", "content_json": {"items": [{"quote": "I can trace my three biggest clients to relationships I built through bar events. The dues pay for themselves.", "name": "Sarah L., Managing Partner"}, {"quote": "As a first-generation lawyer, my mentor through the bar taught me everything law school couldn''t.", "name": "Marcus T., Associate"}]}}, {"section_type": "cta", "content_json": {"heading": "Join now", "cta_label": "Become a Member", "cta_url": "/join"}}]'::jsonb, updated_at = now() WHERE is_global = true AND name = 'Member Benefits';
UPDATE public.website_templates SET default_sections_json = '[{"section_type": "hero", "content_json": {"heading": "Join Our Bar Association", "subheading": "One membership. A career''s worth of connection, education, and support."}}, {"section_type": "pricing_tiers", "content_json": {"tiers": [{"name": "Attorney", "price": "$200/yr", "features": ["All member benefits", "Free live CLE", "Directory listing"]}, {"name": "Young Lawyer", "price": "$100/yr", "features": ["All member benefits", "First 5 years of practice", "Mentorship priority"]}, {"name": "Law Student", "price": "Free", "features": ["Events and networking", "Student writing competition", "Career programs"]}]}}, {"section_type": "contact_form", "content_json": {"heading": "Apply for membership"}}]'::jsonb, updated_at = now() WHERE is_global = true AND name = 'Join / Renew Membership';
UPDATE public.website_templates SET default_sections_json = '[{"section_type": "hero", "content_json": {"heading": "Free and Low-Cost Legal Help", "subheading": "You don''t have to face a legal problem alone. Start here."}}, {"section_type": "resource_cards", "content_json": {"resources": [{"title": "Legal Aid Alliance", "body": "Free civil legal services for qualifying households — housing, family, benefits, and consumer matters.", "cta": "Call (555) 010-4400"}, {"title": "Ask-a-Lawyer Clinics", "body": "Free 20-minute consultations with volunteer attorneys, first Saturday of every month at the public library."}, {"title": "Modest Means Program", "body": "Reduced-fee representation from participating attorneys for those who earn too much for legal aid but can''t afford standard rates."}]}}, {"section_type": "faq", "content_json": {"items": [{"question": "Do I qualify for free legal aid?", "answer": "Most programs serve households up to 200% of the federal poverty guidelines. Each program screens applicants — start with a call."}, {"question": "What should I bring to a clinic?", "answer": "Any court papers, letters, contracts, or notices related to your problem, plus a list of key dates."}, {"question": "Can you help with criminal cases?", "answer": "These resources cover civil matters. If you face criminal charges and cannot afford a lawyer, ask the court to appoint a public defender."}]}}, {"section_type": "cta", "content_json": {"heading": "Need help now?", "cta_label": "Contact Intake", "cta_url": "#"}}]'::jsonb, updated_at = now() WHERE is_global = true AND name = 'Legal Aid Resource Page';
UPDATE public.website_templates SET default_sections_json = '[{"section_type": "hero", "content_json": {"heading": "Annual Judicial Reception", "subheading": "An evening honoring the judges who serve our community"}}, {"section_type": "event_details", "content_json": {"date": "Thursday, October 14 · 5:30–8:00 PM", "location": "The Grand Hall at Meridian House"}}, {"section_type": "cta", "content_json": {"heading": "Join us in honoring the bench", "cta_label": "Reserve Your Place", "cta_url": "#"}}]'::jsonb, updated_at = now() WHERE is_global = true AND name = 'Judicial Reception';
UPDATE public.website_templates SET default_sections_json = '[{"section_type": "hero", "content_json": {"heading": "New Rules for Remote Depositions Take Effect March 1", "subheading": "By the Practice Management Committee"}}, {"section_type": "text", "content_json": {"body": "When the amended rules take effect on March 1, remote depositions will no longer require stipulation in most civil matters. Here''s what changes, what stays the same, and the three things every litigator should update in their notice templates this month. First, the amended Rule 30 presumes remote proceedings are permissible unless a party shows good cause... [Continue your article here — this sample shows how a lede and body will look.]"}}, {"section_type": "newsletter", "content_json": {"heading": "Get articles like this in your inbox monthly"}}]'::jsonb, updated_at = now() WHERE is_global = true AND name = 'Newsletter Article';
UPDATE public.website_templates SET default_sections_json = '[{"section_type": "hero", "content_json": {"heading": "Sponsor Spotlight: Meridian Legal Technologies", "subheading": "Meet the platinum partner behind our CLE streaming"}}, {"section_type": "image_text", "content_json": {"heading": "About Meridian", "body": "Meridian has supported our bar''s programs for six years, and their streaming platform is the reason members in every corner of the county can attend CLE without a drive downtown. We sat down with their team to talk about what''s next for courtroom technology — and why they keep investing in local legal communities."}}, {"section_type": "cta", "content_json": {"heading": "Learn more about Meridian", "cta_label": "Visit Their Site", "cta_url": "#"}}]'::jsonb, updated_at = now() WHERE is_global = true AND name = 'Sponsor Spotlight';
UPDATE public.website_templates SET default_sections_json = '[{"section_type": "hero", "content_json": {"heading": "Volunteer With Us", "subheading": "An hour of your expertise can change the course of someone''s life"}}, {"section_type": "feature_grid", "content_json": {"items": [{"title": "Clinics", "body": "Staff a free Ask-a-Lawyer clinic — one Saturday morning, no ongoing commitment."}, {"title": "Pro Bono Cases", "body": "Take a referred case with mentorship and malpractice coverage provided."}, {"title": "Teach", "body": "Lead a CLE session or speak to students about your practice area."}]}}, {"section_type": "contact_form", "content_json": {"heading": "Tell us how you''d like to help"}}]'::jsonb, updated_at = now() WHERE is_global = true AND name = 'Volunteer Signup';